import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.BUwdTBzS.js";const h=JSON.parse('{"title":"knowledge-loop","description":"AI 驱动的本地代码知识沉淀与复用系统（仅本地 ~/.codebuddy/knowledge/，非 MCP 远程知识库）。自动沉淀每次开发中接触到的接口/数据模型/业务逻辑/UI/易错点等代码相关知识，在后续需求中自动检索复用，让 AI 越用越聪明。与 远程知识库 MCP（remote_kb） 远程…","frontmatter":{"title":"knowledge-loop","description":"AI 驱动的本地代码知识沉淀与复用系统（仅本地 ~/.codebuddy/knowledge/，非 MCP 远程知识库）。自动沉淀每次开发中接触到的接口/数据模型/业务逻辑/UI/易错点等代码相关知识，在后续需求中自动检索复用，让 AI 越用越聪明。与 远程知识库 MCP（remote_kb） 远程…"},"headers":[],"relativePath":"skills/knowledge-loop.md","filePath":"skills/knowledge-loop.md","lastUpdated":null}'),c={name:"skills/knowledge-loop.md"};function l(a,t,s,n,i,g){return d(),o("div",null,[...t[0]||(t[0]=[r('<blockquote><p>📄 本页由源文件 <code>skills/knowledge-loop/SKILL.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="knowledge-loop" tabindex="-1">knowledge-loop <a class="header-anchor" href="#knowledge-loop" aria-label="Permalink to &quot;knowledge-loop&quot;">​</a></h1><p>&lt;!-- ┌──────────────────────────────────────────────────────────────┐ --&gt; &lt;!-- │ ❄️ 冻结横幅 / FROZEN BANNER（Phase 1 重构，2026-05-15） │ --&gt; &lt;!-- ├──────────────────────────────────────────────────────────────┤ --&gt; &lt;!-- │ 本文件是 AI 运行时入口（提示词层），不是规则真相来源。 │ --&gt; &lt;!-- │ │ --&gt; &lt;!-- │ 单一权威源（Single Source of Truth）： │ --&gt; &lt;!-- │ • 前置物 schema → config/frontmatter.schema.json │ --&gt; &lt;!-- │ • 状态机定义 → config/state-machine.yaml │ --&gt; &lt;!-- │ • 阈值/健康度 → config/thresholds.yaml │ --&gt; &lt;!-- │ • 依赖/lint/校验脚本 → scripts/{precheck,lints,lib}/ │ --&gt; &lt;!-- │ • 设计哲学/重构决策 → references/refactor-plan.md │ --&gt; &lt;!-- │ │ --&gt; &lt;!-- │ 修改规则： │ --&gt; &lt;!-- │ 1. 任何「确定性规则」改动必须先动 config/scripts，再回引 │ --&gt; &lt;!-- │ 到本文件；禁止只在提示词里描述硬规则。 │ --&gt; &lt;!-- │ 2. 本文件章节如与 config/scripts 冲突，以 config/scripts 为 │ --&gt; &lt;!-- │ 准；冲突即视为本文件失效，需立即修订。 │ --&gt; &lt;!-- │ 3. 跨文件协作必须双向引用（参考 AI 行为规范.mdc §跨文件 │ --&gt; &lt;!-- │ 协作设计模式）。 │ --&gt; &lt;!-- └──────────────────────────────────────────────────────────────┘ --&gt;</p><blockquote><p><strong>定位</strong>：dev-flow 的唯一<strong>本地代码知识</strong>存储与检索层，让 AI 越用越聪明。 与 远程知识库 MCP（remote_kb） 远程知识库互补——本 skill 是 AI 的「肌肉记忆」（本地、可写、AI 沉淀），知识库平台 是项目的「全景地图」（远程、只读、源码语义检索）。 可被 <code>dev-flow</code> 步骤 1/5/7/10/收尾按需调用，也可独立使用。</p></blockquote><h2 id="与-知识库平台-的边界-重要" tabindex="-1">与 知识库平台 的边界（重要） <a class="header-anchor" href="#与-知识库平台-的边界-重要" aria-label="Permalink to &quot;与 知识库平台 的边界（重要）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>本 skill（knowledge-loop）</th><th>知识库平台 / remote_kb MCP</th></tr></thead><tbody><tr><td>存储位置</td><td>本地 <code>~/.codebuddy/knowledge/{project}/</code></td><td>远程 <code>knowledge_uuid</code></td></tr><tr><td>可写性</td><td>✅ 可写（强制沉淀）</td><td>❌ 只读（被动检索）</td></tr><tr><td>内容形态</td><td>Markdown + YAML（5 主题文件）</td><td>git/git_doc_platform/commit/MR 索引</td></tr><tr><td>数据来源</td><td>AI 沉淀 + 用户验证</td><td>项目源码 + doc_platform + commit + MR</td></tr><tr><td>调用方式</td><td><code>use_skill(&#39;knowledge-loop&#39;)</code></td><td><code>use_mcp_tool(server=remote_kb, tool=knowledgebase_search)</code></td></tr><tr><td>触发词归属</td><td>「代码知识」「本地知识库」「沉淀知识」</td><td>「MCP 知识库」「knowledge_uuid」「remote_kb」「git_doc_platform」</td></tr></tbody></table><blockquote><p>⚠️ 用户说「MCP 知识库」「knowledge_uuid」「remote_kb」「doc_platform」时<strong>不要触发本 skill</strong>——那是 知识库平台 的范畴，应使用 dev-flow 的 知识库平台 MCP 调用机制。</p></blockquote><h2 id="路由规则" tabindex="-1">路由规则 <a class="header-anchor" href="#路由规则" aria-label="Permalink to &quot;路由规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>触发方式</th><th>加载文件</th></tr></thead><tbody><tr><td><strong>检索模式</strong></td><td>dev-flow 步骤 1/5 调用</td><td><code>read_file(&quot;modes/retrieve.md&quot;)</code></td></tr><tr><td><strong>沉淀模式</strong></td><td>dev-flow 步骤 7/10/收尾调用</td><td><code>read_file(&quot;modes/deposit.md&quot;)</code></td></tr><tr><td><strong>管理模式</strong></td><td><code>dev:kb</code> 命令 / 用户主动操作</td><td><code>read_file(&quot;modes/manage.md&quot;)</code></td></tr><tr><td><strong>自动捕获</strong></td><td>非 dev-flow 对话中发现有价值知识</td><td><code>read_file(&quot;modes/auto-capture.md&quot;)</code></td></tr></tbody></table><blockquote><p>💡 <strong>检索模式自带「sync 滞后检测」</strong>：dev-flow 步骤 1 触发检索时，自动比对 <code>_index.md.last_synced_sha</code> 与 <code>origin/{base_branch}</code>，若已偏离/超 7 天/从未 sync 则提示用户先跑 <code>dev:kb sync</code>，避免引用过期 verified 知识。完整规则见 <code>modes/retrieve.md</code> § sync 滞后检测。</p></blockquote><h3 id="加载策略" tabindex="-1">加载策略 <a class="header-anchor" href="#加载策略" aria-label="Permalink to &quot;加载策略&quot;">​</a></h3><ul><li><strong>单一模式</strong>：识别到明确模式后只加载对应文件，不加载其余</li><li><strong>dev-flow 调用时</strong>：dev-flow 步骤说明中会指定模式（如「检索模式」「沉淀模式」），直接加载对应文件</li><li><strong>自动捕获</strong>：非 dev-flow 对话中，AI 检测到有价值的项目知识时，加载 <code>auto-capture.md</code> 执行轻量沉淀</li><li><strong>不确定时</strong>：默认进入管理模式（展示概览+选项）</li></ul><hr><h2 id="dev-flow-集成映射" tabindex="-1">dev-flow 集成映射 <a class="header-anchor" href="#dev-flow-集成映射" aria-label="Permalink to &quot;dev-flow 集成映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>dev-flow 步骤</th><th>模式</th><th>行为</th></tr></thead><tbody><tr><td>步骤 1（研究定位）</td><td>检索</td><td>自动检索项目知识，输出匹配结果；<strong>附带 sync 滞后检测</strong>（<code>last_synced_sha</code> 落后远端 base / 超 7 天未 sync / 从未 sync）</td></tr><tr><td>步骤 5（编码）</td><td>检索</td><td>按改动文件类型动态加载对应主题知识</td></tr><tr><td>步骤 7（清理+Commit）</td><td>沉淀</td><td>标准执行/批次最后一批：强制沉淀（禁止跳过）</td></tr><tr><td>步骤 10（归档交付）</td><td>沉淀</td><td>完整执行：强制沉淀（禁止跳过）</td></tr><tr><td>收尾环节 H.3</td><td>沉淀</td><td>收尾模式：强制沉淀（禁止跳过）</td></tr><tr><td><code>dev:kb</code> / <code>dev:k</code></td><td>管理</td><td>查看/扫描/搜索/健康检查/验证/可视化</td></tr></tbody></table><p><strong>dev-flow 调用约定</strong>：</p><ul><li>dev-flow 通过 <code>use_skill(&#39;knowledge-loop&#39;)</code> 调用，附带模式标识（如「检索模式」「沉淀模式」）</li><li>加载后按模块内部规则执行，无需回到本入口文件</li><li>批次执行非最后一批：跳过沉淀（推迟到最后一批）</li></ul><hr><h2 id="存储位置" tabindex="-1">存储位置 <a class="header-anchor" href="#存储位置" aria-label="Permalink to &quot;存储位置&quot;">​</a></h2><p><code>~/.codebuddy/knowledge/{project-name}/</code> — 三级结构：项目→模块→主题（<code>_index.md</code> / <code>{module}/_overview.md</code> / <code>{data-model,api,logic,ui,pitfalls}.md</code> / <code>_patterns/</code> / <code>_recipes/</code>）。</p><blockquote><p>📌 完整目录树 + 命名规范 + frontmatter schema 详见 <code>references/schema.md</code>。</p></blockquote><hr><h2 id="执行链路-确定性规则的物理事实层" tabindex="-1">执行链路（确定性规则的物理事实层） <a class="header-anchor" href="#执行链路-确定性规则的物理事实层" aria-label="Permalink to &quot;执行链路（确定性规则的物理事实层）&quot;">​</a></h2><blockquote><p><strong>重要</strong>：本 skill 所有「确定性规则」均由 <code>config/</code> + <code>scripts/</code> 兜底。AI 涉及&quot;前置物校验 / 健康度计算 / 状态判定 / 依赖检查&quot;动作时<strong>必须调用脚本而非根据本文件提示词推理</strong>——脚本/配置才是规则真相。</p></blockquote><p><strong>配置权威源</strong>（修改这里即修改规则）：</p><ul><li><code>config/frontmatter.schema.json</code> · <code>config/state-machine.yaml</code> · <code>config/thresholds.yaml</code></li></ul><p><strong>脚本执行入口</strong>（CLI 直接验证 · 退出码语义见 catalog）：</p><ul><li>库：<code>scripts/lib/{yaml-bridge,score,state}.sh</code></li><li>Lint：<code>scripts/lints/check-{frontmatter,state,health,staleness}.sh</code></li><li>守卫：<code>scripts/precheck/check-deps.sh</code></li><li>测试：<code>scripts/tests/run-tests.sh</code>（当前 6 套件 37 用例 · PASS=37 / FAIL=0）</li></ul><p><strong>详尽规约</strong>（CLI 用法 / 退出码语义 / 调用规约 / 设计哲学回引）：见 <code>references/scripts-catalog.md</code>。</p><blockquote><p>📌 任何与脚本输出<strong>冲突</strong>的本文件描述视为本文件失效，需立即修订（与 ❄️ 冻结横幅 §修改规则 第 2 条一致）。设计哲学一句话：<strong>确定性用代码（schema/lint/yaml），模糊性用 LLM</strong>。</p></blockquote><hr><h2 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to &quot;核心原则&quot;">​</a></h2><ul><li><strong>唯一本地来源</strong>：knowledge-loop 是 dev-flow 的唯一<strong>本地代码知识</strong>检索和沉淀目标（远程语义知识用 知识库平台）</li><li><strong>宁多勿少</strong>：不仅沉淀本次需求改动，还要全面沉淀开发过程中接触到的所有模块知识</li><li><strong>按需加载</strong>：知识分主题存储在独立文件中，AI 按需加载而非全量加载，优化 token 效率</li><li><strong>AI 友好</strong>：Markdown 格式，带 YAML frontmatter 元数据，机器可读可写</li><li><strong>强制沉淀</strong>：每次需求完成都必须沉淀，禁止以任何理由跳过</li><li><strong>集中存储</strong>：knowledge/ 统一存储在 <code>~/.codebuddy/knowledge/</code>，禁止在项目目录中创建</li></ul><hr><h2 id="独立使用" tabindex="-1">独立使用 <a class="header-anchor" href="#独立使用" aria-label="Permalink to &quot;独立使用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户说</th><th>AI 行为</th></tr></thead><tbody><tr><td>&quot;帮我沉淀下这个模块的知识&quot;</td><td><code>read_file(&quot;modes/deposit.md&quot;)</code> 进入交互式沉淀</td></tr><tr><td>&quot;查看项目知识库&quot; / <code>dev:kb</code></td><td><code>read_file(&quot;modes/manage.md&quot;)</code> 进入管理模式</td></tr><tr><td>&quot;搜索知识库 xxx&quot; / <code>dev:kb search xxx</code> / <code>dev:k s xxx</code></td><td><code>read_file(&quot;modes/manage.md&quot;)</code> → 搜索</td></tr><tr><td>&quot;扫描代码知识&quot; / `dev:kb scan [module</td><td>--all</td></tr><tr><td>&quot;git pull 后对齐知识库&quot; / &quot;拉了最新 master&quot; / <code>dev:kb sync</code> / <code>dev:k sy</code></td><td><code>read_file(&quot;modes/manage.md&quot;)</code> → §「dev:kb sync」（双场景：他人改动漂移检测 + 自己 pending 升级 verified）</td></tr><tr><td>&quot;知识库健康度&quot; / <code>dev:kb health</code> / <code>dev:k h</code></td><td><code>read_file(&quot;modes/manage.md&quot;)</code> → 健康检查</td></tr><tr><td>&quot;审计自动升级知识&quot; / <code>dev:kb audit</code> / <code>dev:k a</code> / <code>dev:kb audit --all</code> / <code>dev:kb audit --archived</code> / <code>dev:kb audit --reject &lt;id&gt;</code> / <code>dev:kb audit --confirm &lt;id&gt;</code></td><td><code>read_file(&quot;references/confidence.md&quot;)</code> → §「scanned 自动升级规则」「异步审计与反悔机制」</td></tr><tr><td>&quot;验证知识一致性&quot; / <code>dev:kb verify</code> / <code>dev:k v</code></td><td><code>read_file(&quot;modes/manage.md&quot;)</code> → 验证</td></tr><tr><td>&quot;知识地图&quot; / <code>dev:kb dashboard</code> / <code>dev:k d</code></td><td><code>read_file(&quot;modes/manage.md&quot;)</code> → 可视化</td></tr><tr><td>&quot;导出知识库&quot; / <code>dev:kb export --format=xxx</code> / <code>dev:k e xxx</code></td><td><code>read_file(&quot;references/mcp-export.md&quot;)</code> → 导出</td></tr><tr><td>&quot;提升全局模式&quot; / <code>dev:kb promote &lt;pattern&gt;</code></td><td><code>read_file(&quot;references/lifecycle.md&quot;)</code> → 跨项目模式提升</td></tr></tbody></table><hr><h2 id="references-深度参考-按需加载" tabindex="-1">References（深度参考，按需加载） <a class="header-anchor" href="#references-深度参考-按需加载" aria-label="Permalink to &quot;References（深度参考，按需加载）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>用途</th><th>加载时机</th></tr></thead><tbody><tr><td><code>references/schema.md</code></td><td>目录结构规范 + 文件格式 + 项目名称映射</td><td>首次创建项目知识库时</td></tr><tr><td><code>references/confidence.md</code></td><td>置信度体系 + 代码漂移检测逻辑</td><td>检索时发现疑似漂移 / 沉淀时更新置信度</td></tr><tr><td><code>references/lifecycle.md</code></td><td>生命周期管理（过期规则/刷新机制/废弃流程/跨项目提升）</td><td>管理模式的健康检查 / 过期预警 / 模式提升</td></tr><tr><td><code>references/team-sharing.md</code></td><td>团队共享方案（Phase 2 扩展）</td><td>用户询问团队共享时</td></tr><tr><td><code>references/mcp-export.md</code></td><td>跨工具导出与 MCP 集成</td><td>用户要求导出知识库 / 跨工具使用 / MCP 集成</td></tr><tr><td><code>references/scripts-catalog.md</code></td><td>§执行链路 详尽规约（脚本 CLI 用法 / 退出码语义 / 调用规约）</td><td>修改 config 或 scripts / 查脚本输出语义 / 排查与提示词冲突</td></tr><tr><td><code>references/cross-repo-linkage.md</code></td><td>跨仓库参数链路联动写入范例（含 B→A 完整示例 + 3 种常见模式 + 自检清单）</td><td>deposit.md 步骤 5.6 按需加载</td></tr></tbody></table>',39)])])}const m=e(c,[["render",l]]);export{h as __pageData,m as default};
